test('PG18 function definition formatter preserves complete body and correct dollar-prefix collision handling',()=>{
 const hash=get('function','public.order_split210_hash(v jsonb)'),literal=/CREATE FUNCTION public\.order_split210_hash\(v jsonb\) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS \$\$([\s\S]*?)\$\$;/.exec(inputs.source210);
 assert(literal,'independent literal source body anchor');
 assert.equal(hash.known.definition,"CREATE OR REPLACE FUNCTION public.order_split210_hash(v jsonb)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO 'pg_catalog', 'public'\nAS $function$"+literal[1]+'$function$\n');
 const finalize=expected.records.find(r=>r.kind==='function'&&r.key.startsWith('public.order_split210_finalize('));
 assert(finalize.known.definition.includes("\n SET \"TimeZone\" TO 'UTC'\nAS $function$"));
 // Synthetic bodies exercise PG's prefix rule; they never enter the pinned
 // source oracle or become expected records for a real catalogue.
 for(const[source,tag]of [['SELECT $functionality;', '$functionx$'],['SELECT $function$ || $functionx;', '$functionxx$'],['SELECT Żółć;', '$function$']]){
  const text=formatOrderSplit210FunctionDefinition(hash.key,{...hash.known,source});assert(text.endsWith(tag+source+tag+'\n'));
 }
 for(const r of expected.records.filter(r=>r.kind==='function')){
  const tag=/^AS (\$functionx*\$)/m.exec(r.known.definition)?.[1];assert(tag);
  assert(!r.known.source.includes(tag.slice(0,-1)),'PG tests growing prefix, including without final dollar');
  assert(r.known.definition.endsWith(tag+r.known.source+tag+'\n'),'entire actual body, not a truncated first dollar delimiter');
 }
});

