test('sixteen dependent table/array types retain complete catalog metadata and source ACL permissions in required C order',()=>{
 const c=get('type','public.order_split210_targets'),a=get('type','public._order_split210_targets');
 assert.equal(c.unresolved_fields.length,0);assert.equal(a.unresolved_fields.length,0);
 assert.equal(c.known.input,'record_in(cstring,oid,integer)');assert.equal(c.known.send,'record_send(record)');assert.equal(c.known.analyze,null);
 assert.equal(a.known.input,'array_in(cstring,oid,integer)');assert.equal(a.known.send,'array_send(anyarray)');
 assert.equal(a.known.analyze,'array_typanalyze(internal)');assert.equal(a.known.subscript,'array_subscript_handler(internal)');
 for(const r of[c,a]){assert.equal(r.known.length,-1);assert.equal(r.known.by_value,false);assert.equal(r.known.modifier,-1);assert.equal(r.known.dimensions,0);assert.equal(r.known.alignment,'d');assert.equal(r.known.storage,'x');assert.equal(r.known.acl_null,true);
  assert.deepEqual(r.known.acl,[{grantor:'postgres',grantee:'PUBLIC',privilege:'USAGE',grantable:false},{grantor:'postgres',grantee:'postgres',privilege:'USAGE',grantable:false}]);}
 assert.equal(expected.reader_context.database_collation,'C.UTF-8');assert.equal(expected.reader_context.locale_provider,'c');assert.equal(expected.reader_context_verified,false);
 const rows=synthetic(),r=rows.find(r=>r.kind==='type');r.value.acl.reverse();assert.throws(()=>assertOrderSplit210AdditionSemantics(rows,inputs),/source-derived acl/,'no silent collation/order adoption');
});

test('independent48-expression compiler input removes only18 fixed FKs and preserves all literal scalar expressions',()=>{
 const probe=deriveOrderSplit210ExpressionProbe(inputs),unquoted=s=>orderSplit210ObserverSpans(s).map(v=>v.executable?v.text:' '.repeat(v.text.length)).join('');
 assert.deepEqual(probe.counts,{tables:8,removed_foreign_keys:18,check_definitions:44,generated_expressions:4,readback_leaves:48});
 assert.equal(probe.namespace,ORDER_SPLIT210_EXPRESSION_PROBE_SCHEMA);assert.equal(sha(probe.sql),probe.sql_sha256);assert.equal(sha(probe.readback_sql),probe.readback_sha256);
 assert(probe.sql.startsWith('CREATE SCHEMA '+probe.namespace+' AUTHORIZATION postgres;\n'));
 assert.equal((unquoted(probe.sql).match(/\bCREATE TABLE /g)||[]).length,8);
 assert(!/\b(?:REFERENCES|FOREIGN KEY|INSERT|UPDATE|DELETE|DROP|ALTER|GRANT|REVOKE|BEGIN|COMMIT|ROLLBACK|CREATE FUNCTION)\b/.test(unquoted(probe.sql)));
 assert.equal((unquoted(probe.sql).match(/\bCHECK\s*\(/g)||[]).length,44);
 assert.equal((unquoted(probe.sql).match(/\bGENERATED ALWAYS AS\(/g)||[]).length,4);
 for(const r of expected.records){if(r.kind==='constraint'&&r.known.kind==='c')assert(probe.sql.includes(r.authored.expression),'literal CHECK unchanged');if(r.authored.generated_expression)assert(probe.sql.includes(r.authored.generated_expression),'literal generated expression unchanged');}
 assert.equal(probe.table_projections.reduce((n,t)=>n+t.edits.length,0),18);
 for(const t of probe.table_projections){assert.equal(sha(t.source_sql),t.source_sql_sha256);assert.equal(sha(t.sql),t.sql_sha256);assert.equal(t.inverse_verified,true);assert(t.source_sql.startsWith('CREATE TABLE '+t.table+'('));
  for(const e of t.edits){assert(t.source_sql.includes(e.before));assert(/REFERENCES public\./.test(e.before));if(e.after!==null)assert(/^[a-z_][a-z_0-9]* uuid NOT NULL$/.test(e.after.trim()));}}
 assert.equal(new Set(probe.targets.map(r=>r.kind+'\0'+r.key)).size,48);
 assert(probe.readback_sql.includes('pg_catalog.pg_get_constraintdef(k.oid,true)'));assert(probe.readback_sql.includes('pg_catalog.pg_get_expr(d.adbin,d.adrelid)'));
 assert.equal(probe.required_context.unconditional_rollback,true);assert.equal(probe.source_compilation_performed,false);assert.equal(probe.seal_allowed,false);assert.equal(probe.native_certification,false);
 assert.throws(()=>deriveOrderSplit210ExpressionProbe({...inputs,source210:inputs.source210.replace('CHECK(source_version>0)','CHECK(public.fake(source_version)>0)')}),/exact literal source/);
});

test('appended nullable column6 preserves all five original columns and the entire independent Source31 probe',()=>{
 const probe=deriveOrderSplit210ExpressionProbe(inputs),columnKey='public.order_split210_projection_basis.payload_schema';
 const scalar=get('column',columnKey),table=probe.table_projections.find(t=>t.table==='public.order_split210_projection_basis');assert(table);
 assert.equal(scalar.known.position,6);assert.equal(scalar.known.type,'text');assert.equal(scalar.known.not_null,false);assert.equal(scalar.known.generated,'s');
 assert.equal(scalar.known.collation,'"default"');assert.equal(scalar.known.storage,'x');assert.deepEqual(scalar.unresolved_fields,['default']);
 assert.equal(scalar.authored.declaration,"payload_schema text GENERATED ALWAYS AS((payload::jsonb)->>'schema') STORED");
 assert.equal(scalar.authored.generated_expression,"(payload::jsonb)->>'schema'");
 const addition=','+scalar.authored.declaration;assert.equal(table.source_sql.split(addition).length,2);assert(table.source_sql.endsWith(addition+');'));
 const oldTable=table.source_sql.replace(addition,'');assert.equal(Buffer.byteLength(oldTable),627);assert.equal(sha(oldTable),'e1b1c0cbd44ffe0a69597b8129901ad171fcc2487adb3db962ff32496443c42f');
 const originalColumns=['id','payload','payload_jsonb','payload_octets','payload_sha256'];
 for(const[name,index]of originalColumns.map((name,index)=>[name,index]))assert.equal(get('column','public.order_split210_projection_basis.'+name).known.position,index+1);
 assert(!expected.records.some(r=>r.kind==='constraint'&&r.key.endsWith('.order_split210_projection_basis_payload_schema_not_null')),'nullable scalar introduces no NOT NULL constraint');
 const historicalSql=probe.sql.replace(addition,'');assert.equal(Buffer.byteLength(historicalSql),6207);
 assert.equal(sha(historicalSql),'13a717d9a67551e18c59110350168594e32940dce02dd8a5f680a880250601fa','whole authored Source31 P23 SQL, not an updated approximation');
 const readbackAddition=",'order_split210_projection_basis.payload_schema'";assert.equal(probe.readback_sql.split(readbackAddition).length,2);
 const historicalReadback=probe.readback_sql.replace(readbackAddition,'');assert.equal(Buffer.byteLength(historicalReadback),4069);
 assert.equal(sha(historicalReadback),'a51b4d20866fa49925e64937dd25715b0820569657974d9b9195223cfa3675aa','whole historical47-key readback');
 assert.deepEqual(probe.targets.filter(t=>t.key===columnKey),[{kind:'column',key:columnKey,field:'default'}]);
 const historicalTargets=probe.targets.filter(t=>t.key!==columnKey),canonical=v=>Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v;
 assert.equal(historicalTargets.length,47);const targets=JSON.stringify(canonical(historicalTargets));assert.equal(Buffer.byteLength(targets),5802);
 assert.equal(sha(targets),'e08dcb64a07f8ec2b863dfa49ae24b9447e77439eb78b441b6c89c88d4d53036','all original47 target identities and fields preserved');
});

test('known body/ACL/nullability/index flags/owner-policy/RI/type changes refuse independently of matching names',()=>{
 const examples=[
  ['function',r=>r.key==='public.order_split210_hash(v jsonb)','source',v=>v+'\n'],
  ['function',r=>r.key==='public.order_split210_hash(v jsonb)','acl',v=>[...v,{grantor:'postgres',grantee:'dyna_app',privilege:'EXECUTE',grantable:false}]],
  ['column',r=>r.key==='public.order_split210_targets.slot_id','not_null',()=>true],
  ['column',r=>r.key==='public.order_split210_projection_basis.payload_schema','not_null',()=>true],
  ['column',r=>r.key==='public.order_split210_projection_basis.payload_schema','position',()=>5],
  ['column',r=>r.key==='public.order_split210_projection_basis.payload_schema','generated',()=> ''],
  ['index',r=>r.key==='public.order_split210_single_remainder','unique',()=>false],
  ['policy',()=>true,'roles',()=>['PUBLIC']],
  ['trigger',r=>r.value.internal,'deferrable',v=>!v],
  ['type',r=>r.key==='public._order_split210_targets','element',()=>null],
 ];
 for(const[kind,select,field,mutate]of examples){const rows=synthetic(),r=rows.find(r=>r.kind===kind&&select(r));assert(r);r.value[field]=mutate(r.value[field]);assert.throws(()=>assertOrderSplit210AdditionSemantics(rows,inputs),new RegExp('source-derived '+field));}
});

test('no prefix adoption: missing/extra/duplicate/overloaded/external additions and truncated metadata refuse',()=>{
 const missing=synthetic();missing.pop();assert.throws(()=>assertOrderSplit210AdditionSemantics(missing,inputs),/exact source-derived addition roster/);
 const extra=synthetic();extra.push({...structuredClone(extra.find(r=>r.kind==='function')),key:'public.order_split210_invented()'});assert.throws(()=>assertOrderSplit210AdditionSemantics(extra,inputs),/exact source-derived addition roster/);
 const dup=synthetic();dup.push(dup[0]);assert.throws(()=>assertOrderSplit210AdditionSemantics(dup,inputs),/duplicate addition/);
 const external=synthetic(),ri=external.find(r=>r.kind==='trigger'&&r.value.internal&&!r.key.startsWith('public.order_split210_'));ri.key+='foreign';assert.throws(()=>assertOrderSplit210AdditionSemantics(external,inputs),/exact source-derived addition roster/);
 const truncated=synthetic();delete truncated.find(r=>r.kind==='function').value.definition;assert.throws(()=>assertOrderSplit210AdditionSemantics(truncated,inputs),/complete canonical metadata fields/);
 const expanded=synthetic();expanded[0].value.unknown=true;assert.throws(()=>assertOrderSplit210AdditionSemantics(expanded,inputs),/complete canonical metadata fields/);
});

test('bounded plain JSON validation refuses accessors/falsy nonrecords without invoking them',()=>{
 let invoked=false;const record={kind:'relation',key:'public.order_split210_targets'};Object.defineProperty(record,'value',{enumerable:true,get(){invoked=true;throw Error('must not invoke');}});
 assert.throws(()=>assertOrderSplit210AdditionSemantics([record],inputs),/data properties only/);assert.equal(invoked,false);
 assert.throws(()=>assertOrderSplit210AdditionSemantics([false],inputs));
 assert.throws(()=>assertOrderSplit210AdditionSemantics([{kind:'function',key:'x',value:NaN}],inputs),/finite JSON/);
 assert.throws(()=>assertOrderSplit210AdditionSemantics(Array(10001),inputs),/bounded addition/);
});
